from collections import deque, defaultdict


def min_jumps(arr):
    n = len(arr)
    if n == 1:
        return 0

    value_to_indices = defaultdict(list)
    for i, v in enumerate(arr):
        value_to_indices[v].append(i)

    visited = [False] * n
    visited[0] = True
    queue = deque([(0, 0)])

    while queue:
        i, steps = queue.popleft()
        if i == n - 1:
            return steps

        candidates = value_to_indices[arr[i]] + [i - 1, i + 1]
        for j in candidates:
            if 0 <= j < n and not visited[j]:
                visited[j] = True
                queue.append((j, steps + 1))

    return -1


if __name__ == "__main__":
    print(min_jumps([100, -23, -23, 404, 100, 23, 23, 23, 3, 404]))
    print(min_jumps([7, 6, 9, 6, 9, 6, 9, 7]))

