import java.util.*;

public class Main {
    static int minJumps(int[] arr) {
        int n = arr.length;
        if (n == 1) return 0;

        Map<Integer, List<Integer>> valueToIndices = new HashMap<>();
        for (int i = 0; i < n; i++) {
            valueToIndices.computeIfAbsent(arr[i], k -> new ArrayList<>()).add(i);
        }

        boolean[] visited = new boolean[n];
        visited[0] = true;
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{0, 0});

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int i = cur[0], steps = cur[1];
            if (i == n - 1) return steps;

            List<Integer> candidates = new ArrayList<>(valueToIndices.get(arr[i]));
            candidates.add(i - 1);
            candidates.add(i + 1);
            for (int j : candidates) {
                if (j >= 0 && j < n && !visited[j]) {
                    visited[j] = true;
                    queue.add(new int[]{j, steps + 1});
                }
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        System.out.println(minJumps(new int[]{100, -23, -23, 404, 100, 23, 23, 23, 3, 404}));
        System.out.println(minJumps(new int[]{7, 6, 9, 6, 9, 6, 9, 7}));
    }
}

