public class Main {
    static int minJumps(int[] arr) {
        int n = arr.length;
        if (n == 1) return 0;

        Map<Integer, List<Integer>> valueToIndices = new HashMap<>();
        for (int i = 0; i < n; i++) {
            valueToIndices.computeIfAbsent(arr[i], k -> new ArrayList<>()).add(i);
        }

        boolean[] visited = new boolean[n];
        visited[0] = true;
        Queue<Integer> queue = new LinkedList<>();
        queue.add(0);
        int steps = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int k = 0; k < size; k++) {
                int i = queue.poll();
                if (i == n - 1) return steps;

                int v = arr[i];
                if (valueToIndices.containsKey(v)) {
                    for (int j : valueToIndices.get(v)) {
                        if (!visited[j]) {
                            visited[j] = true;
                            queue.add(j);
                        }
                    }
                    valueToIndices.remove(v);
                }

                if (i - 1 >= 0 && !visited[i - 1]) { visited[i - 1] = true; queue.add(i - 1); }
                if (i + 1 < n && !visited[i + 1]) { visited[i + 1] = true; queue.add(i + 1); }
            }
            steps++;
        }
        return -1;
    }

    public static void main(String[] args) {
        System.out.println(minJumps(new int[]{100, -23, -23, 404, 100, 23, 23, 23, 3, 404}));
        System.out.println(minJumps(new int[]{7, 6, 9, 6, 9, 6, 9, 7}));
    }
